//! ATS source index and implementation resources; journal articles have separate access.
use super::pmc_crosswalk::{self as cw,Lookup,Planned,SourceRef};
use super::{common,Adapter,PlanRow};
use crate::guidelines::{doc::{GuidelineDoc,Rights},fetch::Fetcher,html::{blocks_from_html,sel,text_of},registry::SourceEntry};
use anyhow::{bail,Context,Result};use scraper::Html;use serde_json::json;use std::collections::{HashSet,VecDeque};use url::Url;
pub struct Ats;
const ROOT:&str="https://site.thoracic.org/clinicians-researchers/clinical-practice-guidelines-statements-reports";
const TOOLS:&str="https://www.thoracic.org/statements/guideline-implementation-tools/index.php";
fn page(raw:&str,base:&Url)->Result<(String,String,String,Vec<serde_json::Value>)>{let d=Html::parse_document(raw);let implementation=base.host_str()==Some("www.thoracic.org")&&base.path().starts_with("/statements/guideline-implementation-tools/");let (root,title,role)=if implementation{let r=d.select(&sel("#layout-content")).next().context("ATS implementation root missing")?;let t=r.select(&sel("#layout-content-title")).next().map(|x|text_of(&x)).context("ATS implementation title missing")?;if !t.contains("Implementation Tools")&&!d.select(&sel("#layout-main-title-secondary h2")).any(|h|text_of(&h)=="Guideline Implementation Tools"){bail!("ATS implementation label missing")};let role=if base.path().ends_with("/index.php"){"implementation_directory"}else{"implementation_tools"};(r,t,role)}else{if base.host_str()!=Some("site.thoracic.org"){bail!("ATS unsupported source host")};let r=d.select(&sel("main#content")).next().context("ATS source index root missing")?;let t=r.select(&sel("h1")).next().map(|x|text_of(&x)).context("ATS source index title missing")?;if !t.contains("Clinical Practice Guidelines"){bail!("ATS index title missing")};(r,t,"source_index")};let primary_urls:HashSet<String>=if implementation&&role!="implementation_directory"{root.select(&sel("ul")).next().and_then(|list|list.select(&sel("li")).next()).map(|li|li.select(&sel("a[href]")).filter_map(|a|a.value().attr("href").and_then(|h|common::link(base,h))).collect()).unwrap_or_default()}else{HashSet::new()};let mut links=vec![];for a in root.select(&sel("a[href]")){let label=text_of(&a);let Some(url)=a.value().attr("href").and_then(|x|common::link(base,x)) else{continue};let related=implementation&&role!="implementation_directory"&&!primary_urls.contains(&url);let role=match label.as_str(){"Full-Length Version"|"Full Text"=>"full_guideline_terminal","Executive Summary"|"Executive Summary PDF"=>"executive_summary","Online Supplement"|"Supplements"=>"supplement","Abstract"=>"abstract","Erratum"=>"erratum","Read the latest ATS guidelines"=>"publisher_catalog",_ if role=="implementation_directory" && Url::parse(&url).map(|x|x.host_str()==Some("www.thoracic.org")&&x.path().starts_with("/statements/guideline-implementation-tools/")&&x.path().ends_with(".php")&&!x.path().ends_with("/index.php")).unwrap_or(false)=>"implementation_topic",_=>continue};links.push(json!({"url":url,"label":label,"role":if related{"related_source_resource"}else{role},"source_label_scope":if related{"outside primary guideline citation; original source label retained"}else{"source-labelled resource"},"rights":"unknown"}));}Ok((title,root.html(),role.into(),links))}
fn issue(s:&SourceEntry,u:String,e:String)->PlanRow{PlanRow{source_id:s.id.clone(),doc_key:format!("ats-{}-unresolved",common::short_hash(&u)),url:u,title:None,rendition:None,version:None,extra:json!({"discovery_error":e})}}
#[async_trait::async_trait]impl Adapter for Ats{
 async fn discover(&self,s:&SourceEntry,f:&Fetcher,limit:Option<usize>)->Result<Vec<PlanRow>>{if limit==Some(0){return Ok(vec![])}let start=s.catalog_url.as_deref().unwrap_or(ROOT);let mut q=VecDeque::from([start.to_string()]);if start==ROOT{q.push_back(TOOLS.into())}let mut seen=HashSet::new();let mut rows=cw::enumerate(s,f,"ats",limit,&HashSet::new()).await?;if limit.is_some_and(|n|rows.len()>=n){return Ok(rows)}let mut pmcids:HashSet<String>=rows.iter().filter_map(cw::row_pmcid).collect();let mut deferred=vec![];let mut dois=HashSet::new();while let Some(url)=q.pop_front(){if !seen.insert(url.clone()){continue}if seen.len()>500{rows.push(issue(s,url,"ATS source page bound exceeded".into()));break}let p=match f.get_ok(&url).await{Ok(x)=>x,Err(e)=>{rows.push(issue(s,url,format!("ATS source page unavailable: {e:#}")));if limit.is_some_and(|n|rows.len()>=n){return Ok(rows)}continue}};let b=Url::parse(&p.record.final_url)?;if b.host_str()!=Url::parse(&url)?.host_str(){rows.push(issue(s,url,"ATS source page redirected outside host".into()));continue}let(title,body,role,links)=match page(&p.text(),&b){Ok(x)=>x,Err(e)=>{rows.push(issue(s,url,format!("ATS source template: {e:#}")));continue}};for l in &links{if l["role"]=="implementation_topic"{if let Some(u)=l["url"].as_str(){q.push_back(u.to_string())}}}let hash=crate::common::sha256_hex(serde_json::to_string(&(&title,&body,&role,&links))?.as_bytes());rows.push(PlanRow{source_id:s.id.clone(),doc_key:format!("ats-{}-{}",common::short_hash(&url),&hash[..12]),url:url.clone(),title:Some(title),rendition:Some("html".into()),version:None,extra:json!({"snapshot":hash})});if limit.is_some_and(|n|rows.len()>=n){return Ok(rows)}for l in links{if l["role"]!="full_guideline_terminal"&&l["role"]!="publisher_catalog"{continue}let Some(target)=l["url"].as_str()else{continue};
 // A source-labelled full-length link states the article DOI: use an Open Access PMC copy when PMC has one.
 let mut crosswalk="no DOI stated by the source link".to_string();
 if l["role"]=="full_guideline_terminal"{if let Some(doi)=cw::doi_from_url(target){if !dois.insert(doi.clone()){continue}let sref=SourceRef{source_url:target.into(),evidence_url:Some(url.clone()),source_title:None,item_type:Some("guideline".into()),key_prefix:"ats".into(),id_route:"source_doi".into(),notes:vec![]};
  match cw::plan(s,f,Lookup::Doi(doi.clone()),sref,json!({"source_landing":url,"source_doi":doi})).await?{Planned::Open(row)=>{if !pmcids.insert(cw::row_pmcid(&row).unwrap_or_default()){continue}rows.push(row);if limit.is_some_and(|n|rows.len()>=n){return Ok(rows)}continue}Planned::Closed{reason,..}=>crosswalk=format!("DOI {doi}: {reason}")}}}
 let reason=match f.get_ok(target).await{Err(e)=>format!("ATS publisher terminal unavailable: {e:#}; open-access crosswalk: {crosswalk}"),Ok(_)=>format!("ATS publisher response received; its independent clinical template and rights remain unvalidated; open-access crosswalk: {crosswalk}")};let mut row=issue(s,target.into(),reason);row.extra["source_landing"]=json!(url);row.extra["role"]=l["role"].clone();
 // The publisher catalog link is a coverage fact, not a document: report it after the source's own items.
 if l["role"]=="publisher_catalog"{deferred.push(row);continue}
 rows.push(row);if limit.is_some_and(|n|rows.len()>=n){return Ok(rows)}}}
 for row in deferred{if limit.is_some_and(|n|rows.len()>=n){break}rows.push(row)}Ok(rows)}
 async fn extract(&self,s:&SourceEntry,f:&Fetcher,r:&PlanRow)->Result<GuidelineDoc>{if cw::is_crosswalk_row(r){return cw::extract(s,f,r).await}if let Some(e)=r.extra["discovery_error"].as_str(){bail!("{e}")};let p=f.get_ok(&r.url).await?;let b=Url::parse(&p.record.final_url)?;if b.host_str()!=Url::parse(&r.url)?.host_str(){bail!("ATS source redirected outside host")};let(title,body,role,links)=page(&p.text(),&b)?;let hash=crate::common::sha256_hex(serde_json::to_string(&(&title,&body,&role,&links))?.as_bytes());if r.extra["snapshot"].as_str()!=Some(hash.as_str()){bail!("ATS page changed; re-plan")};let(blocks,mut warnings)=blocks_from_html(&body,Some(&b),None);warnings.push("ATS source index or implementation page only; full article, abstract, executive summary, supplement and erratum are separate publisher resources. Linked rights and complete guideline content are not established; source inventory is not reconciled.".into());Ok(GuidelineDoc{source_id:s.id.clone(),doc_key:r.doc_key.clone(),work_key:Some(format!("ats-{}",common::short_hash(&r.url))),title,url:r.url.clone(),item_type:Some(role),status:"unknown".into(),rights:Rights{status:"unknown".into(),note:Some("Publisher pages and each linked rendition have independent rights.".into()),..Default::default()},blocks,attachments:links,fetches:vec![p.record],warnings,..Default::default()})}
}
#[cfg(all(test, feature = "guideline-fixtures"))]mod tests{use super::*;const CAT:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/ats/research-1.html"));const OXY:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/ats/research-2.html"));const URL:&str="https://www.thoracic.org/statements/guideline-implementation-tools/home-oxygen-therapy-for-adults.php";
#[test]fn real_source_scopes_and_distinct_publication_roles(){let(_,_,role,links)=page(CAT,&Url::parse(ROOT).unwrap()).unwrap();assert_eq!(role,"source_index");assert!(links.iter().any(|a|a["role"]=="publisher_catalog"));let(t,body,role,links)=page(OXY,&Url::parse(URL).unwrap()).unwrap();assert!(t.contains("Home Oxygen Therapy")&&t.contains("Implementation Tools"));assert_eq!(role,"implementation_tools");assert!(!body.contains("Overview</h3>"));for role in ["full_guideline_terminal","executive_summary","supplement","abstract","erratum"]{assert!(links.iter().any(|l|l["role"]==role),"missing {role}");}}
#[tokio::test]async fn real_oxygen_page_remains_partial_and_terminal_failure_separate(){let t=tempfile::tempdir().unwrap();let f=Fetcher::new(t.path(),true,500,1<<20,"").unwrap();f.seed_cache_for_tests(URL,OXY.as_bytes(),"text/html");let s:SourceEntry=serde_json::from_value(json!({"id":"ats","access":"public","enabled":true,"catalog_url":URL})).unwrap();let rows=Ats.discover(&s,&f,None).await.unwrap();assert_eq!(rows.len(),2);let d=Ats.extract(&s,&f,&rows[0]).await.unwrap();assert_eq!(d.item_type.as_deref(),Some("implementation_tools"));assert!(d.attachments.iter().any(|a|a["role"]=="erratum"));assert!(rows[1].extra["discovery_error"].is_string());assert!(d.warnings.iter().any(|s|s.contains("separate publisher resources")));}
}

#[cfg(all(test, feature = "guideline-fixtures"))]mod source_graph_round_ad{use super::*;const INDEX:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/ats/tools-index.html"));const OXY:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/ats/research-2.html"));const OXY_URL:&str="https://www.thoracic.org/statements/guideline-implementation-tools/home-oxygen-therapy-for-adults.php";
#[test]fn genuine_directory_emits_topic_pages(){let(_,_,role,links)=page(INDEX,&Url::parse(TOOLS).unwrap()).unwrap();assert_eq!(role,"implementation_directory");assert!(links.iter().any(|a|a["role"]=="implementation_topic"&&a["url"]==OXY_URL));}
#[tokio::test]async fn directory_traverses_oxygen_and_keeps_journal_independent(){let t=tempfile::tempdir().unwrap();let f=Fetcher::new(t.path(),true,500,1<<20,"").unwrap();f.seed_cache_for_tests(TOOLS,INDEX.as_bytes(),"text/html");f.seed_cache_for_tests(OXY_URL,OXY.as_bytes(),"text/html");let s:SourceEntry=serde_json::from_value(json!({"id":"ats","access":"public","enabled":true,"catalog_url":TOOLS})).unwrap();let rows=Ats.discover(&s,&f,Some(100)).await.unwrap();let row=rows.iter().find(|x|x.url==OXY_URL&&x.extra["snapshot"].is_string()).unwrap();let d=Ats.extract(&s,&f,row).await.unwrap();assert_eq!(d.item_type.as_deref(),Some("implementation_tools"));assert!(d.attachments.iter().any(|x|x["role"]=="full_guideline_terminal"));assert!(rows.iter().any(|x|x.extra["source_landing"]==OXY_URL&&x.extra["discovery_error"].is_string()));}
}

#[cfg(all(test, feature = "guideline-fixtures"))]mod live_implementation_variants{use super::*;const IPF:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/ats/ipf.html"));const REHAB:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/ats/rehab.html"));const IPF_URL:&str="https://www.thoracic.org/statements/guideline-implementation-tools/matrix-guidelines-and-derivatives-ipf-update.php";const REHAB_URL:&str="https://www.thoracic.org/statements/guideline-implementation-tools/matrix-guidelines-and-derivatives-pulmonary-rehab-in-adults-08-23-23.php";
#[test]fn actual_variant_keeps_title_and_distinct_source_roles(){for (raw,url) in [(IPF,IPF_URL),(REHAB,REHAB_URL)]{let(t,_,role,links)=page(raw,&Url::parse(url).unwrap()).unwrap();assert!(t.contains("Clinical Practice Guideline"));assert_eq!(role,"implementation_tools");for r in ["full_guideline_terminal","abstract","supplement"]{assert!(links.iter().any(|a|a["role"]==r),"missing {r}");}}let(_,_,_,links)=page(REHAB,&Url::parse(REHAB_URL).unwrap()).unwrap();assert!(links.iter().any(|a|a["role"]=="executive_summary"&&a["label"]=="Executive Summary PDF"));}
#[tokio::test]async fn real_variant_remains_partial_when_publisher_unavailable(){let t=tempfile::tempdir().unwrap();let f=Fetcher::new(t.path(),true,500,1<<20,"").unwrap();f.seed_cache_for_tests(REHAB_URL,REHAB.as_bytes(),"text/html");let s:SourceEntry=serde_json::from_value(json!({"id":"ats","access":"public","enabled":true,"catalog_url":REHAB_URL})).unwrap();let rows=Ats.discover(&s,&f,Some(2)).await.unwrap();assert_eq!(rows.len(),2);let d=Ats.extract(&s,&f,&rows[0]).await.unwrap();assert_eq!(d.item_type.as_deref(),Some("implementation_tools"));assert!(d.attachments.iter().any(|a|a["role"]=="executive_summary"));assert!(rows[1].extra["discovery_error"].is_string());assert!(d.warnings.iter().any(|x|x.contains("not established")));}
}
